def gen(rng):
    def dig(x):
        return ' '.join(str(x))

    def fmt(a, b):
        return f"{len(str(a))}\n{dig(a)}\n{len(str(b))}\n{dig(b)}"

    def rd(k):
        return int(str(rng.randint(1, 9)) + ''.join(rng.choice('0123456789') for _ in range(k - 1)))

    tests = [fmt(0, 1), fmt(0, 7), fmt(1, 1), fmt(7, 9), fmt(1234, 25), fmt(100000 - 1, 1), fmt(99999, 99999), fmt(50000, 3), fmt(10, 10)]
    for _ in range(20):
        a = rng.randint(0, 99999)
        b = rng.randint(1, rng.choice([9, 99, 999, 99999]))
        tests.append(fmt(a, b))
    for _ in range(5):
        b = rng.randint(1, 300)
        tests.append(fmt(b * rng.randint(0, 300), b))
    tests.append(fmt(rd(500), rd(250)))
    tests.append(fmt(rd(500), 1))
    tests.append(fmt(rd(500), rd(3)))
    tests.append(fmt(10 ** 499, 10 ** 250))
    tests.append(fmt(10 ** 500 - 1, 10 ** 250 - 1))
    tests.append(fmt(rd(500), rd(499)))
    tests.append(fmt(rd(500), rd(500)))
    tests.append(fmt(rd(300), 7))
    tests.append(fmt(rd(400), rd(200)))
    return tests

